def maxProduct(words: list[str]) -> int:
    masks = {}
    for w in words:
        mask = 0
        for c in w: mask |= (1 << (ord(c) - ord('a')))
        masks[mask] = max(masks.get(mask, 0), len(w))
    max_prod = 0
    for m1, len1 in masks.items():
        for m2, len2 in masks.items():
            if (m1 & m2) == 0:
                max_prod = max(max_prod, len1 * len2)
    return max_prod

